local WaxTabletMaker = {}
local PRODUCTS = {
    iron_wax_tablet = { name = "Železna voščena tablica", ironCost = 1, woodCost = 3, leatherCost = 2, time = 4, cost = 130, prestige = 3, happiness = 2, description = "Železna voščena tablica za pisarje." },
    bronze_wax_tablet = { name = "Bronasta voščena tablica", bronzeCost = 1, ironCost = 1, woodCost = 3, leatherCost = 2, time = 6, cost = 320, prestige = 5, happiness = 3, description = "Bronasta voščena tablica za pisarne." },
    silver_wax_tablet = { name = "Srebrna voščena tablica", silverCost = 1, bronzeCost = 1, ironCost = 1, woodCost = 3, leatherCost = 2, time = 10, cost = 780, prestige = 10, happiness = 4, description = "Srebrna voščena tablica za plemiške pisarje." },
    gilded_wax_tablet = { name = "Pozlačena voščena tablica", goldCost = 1, silverCost = 1, bronzeCost = 1, woodCost = 3, leatherCost = 2, time = 14, cost = 1700, prestige = 19, happiness = 5, description = "Pozlačena voščena tablica za dvorne pisarje." },
    jewel_set_wax_tablet = { name = "Draguljasta voščena tablica", goldCost = 2, silverCost = 1, jewelCost = 1, bronzeCost = 1, woodCost = 3, leatherCost = 2, time = 18, cost = 3700, prestige = 35, happiness = 7, description = "Draguljasta voščena tablica za kraljevske pisarje." },
    royal_sovereign_wax_tablet = { name = "Kraljevski suverena voščena tablica", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 4, leatherCost = 2, time = 25, cost = 8000, prestige = 67, happiness = 13, description = "Suverena voščena tablica z biseri za krono." },
}
local BUILDINGS = {
    waxtablet_workshop = { name = "Voščena delavnica", cost = { gold = 295, wood = 185, stone = 120, iron = 5 }, upkeep = 5, qualityBonus = 5 },
    waxtablet_house = { name = "Voščena hiša", cost = { gold = 1100, wood = 370, stone = 255, silver = 6, iron = 6 }, upkeep = 23, qualityBonus = 18 },
    master_waxtablet_atelier = { name = "Mojstrski voščeni atelje", cost = { gold = 2850, wood = 430, stone = 495, silver = 32, gold = 6 }, upkeep = 67, qualityBonus = 30 },
    sovereign_waxtablet_palace = { name = "Suverena voščena palača", cost = { gold = 12400, wood = 650, stone = 800, gold = 79, jewel = 18 }, upkeep = 245, qualityBonus = 55, prestigeBonus = 50 },
}
WaxTabletMaker.ironStock = 10; WaxTabletMaker.bronzeStock = 8; WaxTabletMaker.woodStock = 18; WaxTabletMaker.leatherStock = 12; WaxTabletMaker.silverStock = 8; WaxTabletMaker.goldStock = 6; WaxTabletMaker.jewelStock = 4; WaxTabletMaker.pearlStock = 4
WaxTabletMaker.productStock = {}; WaxTabletMaker.buildings = {}; WaxTabletMaker.maker = nil; WaxTabletMaker.activeMaking = {}; WaxTabletMaker.totalProducts = 0; WaxTabletMaker.dayTimer = 0
function WaxTabletMaker.init() WaxTabletMaker.ironStock=10; WaxTabletMaker.bronzeStock=8; WaxTabletMaker.woodStock=18; WaxTabletMaker.leatherStock=12; WaxTabletMaker.silverStock=8; WaxTabletMaker.goldStock=6; WaxTabletMaker.jewelStock=4; WaxTabletMaker.pearlStock=4; WaxTabletMaker.productStock={}; WaxTabletMaker.buildings={}; WaxTabletMaker.maker=nil; WaxTabletMaker.activeMaking={}; WaxTabletMaker.totalProducts=0; WaxTabletMaker.dayTimer=0; print("[WaxTabletMaker] Royal Wax Tablet Maker System initialized (6 products, 4 buildings)") end
function WaxTabletMaker.hireMaker(n,s) s=s or math.random(55,90); local c=565+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; WaxTabletMaker.maker={name=n or ("Voščar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Voščar najet: %s (spretnost: %d)",WaxTabletMaker.maker.name,s),"success") end; return true end
function WaxTabletMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function WaxTabletMaker.build(id) local ok,e=WaxTabletMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(WaxTabletMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function WaxTabletMaker.getQualityBonus() local b=0; for _,bd in ipairs(WaxTabletMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function WaxTabletMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and WaxTabletMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and WaxTabletMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and WaxTabletMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and WaxTabletMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and WaxTabletMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and WaxTabletMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and WaxTabletMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and WaxTabletMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #WaxTabletMaker.buildings==0 then return false,"Potrebna voščena delavnica" end; if not WaxTabletMaker.maker then return false,"Potreben voscar" end; return true end
function WaxTabletMaker.make(pt,qty) qty=qty or 1; local ok,e=WaxTabletMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then WaxTabletMaker.ironStock=WaxTabletMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then WaxTabletMaker.bronzeStock=WaxTabletMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then WaxTabletMaker.woodStock=WaxTabletMaker.woodStock-d.woodCost*qty end; if d.leatherCost then WaxTabletMaker.leatherStock=WaxTabletMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then WaxTabletMaker.silverStock=WaxTabletMaker.silverStock-d.silverCost*qty end; if d.goldCost then WaxTabletMaker.goldStock=WaxTabletMaker.goldStock-d.goldCost*qty end; if d.jewelCost then WaxTabletMaker.jewelStock=WaxTabletMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then WaxTabletMaker.pearlStock=WaxTabletMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if WaxTabletMaker.maker then t=math.max(1,t-math.floor(WaxTabletMaker.maker.skill/13)) end; table.insert(WaxTabletMaker.activeMaking,{id="waxtablet_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function WaxTabletMaker.completeMaking(m) local q=1.0+(WaxTabletMaker.getQualityBonus()/100); if WaxTabletMaker.maker then q=q+(WaxTabletMaker.maker.skill/140) end; q=math.min(2.5,q); WaxTabletMaker.productStock[m.productType]=(WaxTabletMaker.productStock[m.productType] or 0)+m.quantity; WaxTabletMaker.totalProducts=WaxTabletMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if WaxTabletMaker.maker then WaxTabletMaker.maker.itemsMade=WaxTabletMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then WaxTabletMaker.maker.skill=math.min(100,WaxTabletMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Tablica izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"waxtablet.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function WaxTabletMaker.update(dt) if not _G.state then return end; WaxTabletMaker.dayTimer=WaxTabletMaker.dayTimer+dt; if WaxTabletMaker.dayTimer>=30 then WaxTabletMaker.dayTimer=0; for i=#WaxTabletMaker.activeMaking,1,-1 do local m=WaxTabletMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then WaxTabletMaker.completeMaking(m); table.remove(WaxTabletMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(WaxTabletMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if WaxTabletMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function WaxTabletMaker.getStats() return {ironStock=WaxTabletMaker.ironStock,bronzeStock=WaxTabletMaker.bronzeStock,woodStock=WaxTabletMaker.woodStock,leatherStock=WaxTabletMaker.leatherStock,silverStock=WaxTabletMaker.silverStock,goldStock=WaxTabletMaker.goldStock,jewelStock=WaxTabletMaker.jewelStock,pearlStock=WaxTabletMaker.pearlStock,productStock=WaxTabletMaker.productStock,numBuildings=#WaxTabletMaker.buildings,hasMaker=WaxTabletMaker.maker~=nil,makerName=WaxTabletMaker.maker and WaxTabletMaker.maker.name or "—",makerSkill=WaxTabletMaker.maker and WaxTabletMaker.maker.skill or 0,activeMaking=#WaxTabletMaker.activeMaking,totalProducts=WaxTabletMaker.totalProducts} end
return WaxTabletMaker
